"use strict";(self.webpackChunkaegis_docs=self.webpackChunkaegis_docs||[]).push([[602],{1402:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"docsSidebar":[{"type":"link","href":"/aegis/docs/what-is-aegis","label":"What is Aegis?","docId":"what-is-aegis","unlisted":false},{"type":"category","label":"Using Aegis","items":[{"type":"link","href":"/aegis/docs/using-aegis/submitting-a-query","label":"Submitting a Query","docId":"using-aegis/submitting-a-query","unlisted":false},{"type":"link","href":"/aegis/docs/using-aegis/monitoring-a-job","label":"Monitoring a Job","docId":"using-aegis/monitoring-a-job","unlisted":false},{"type":"link","href":"/aegis/docs/using-aegis/reading-results","label":"Reading Results","docId":"using-aegis/reading-results","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"How It Works","items":[{"type":"link","href":"/aegis/docs/how-it-works/data-pipeline","label":"Data Pipeline","docId":"how-it-works/data-pipeline","unlisted":false},{"type":"link","href":"/aegis/docs/how-it-works/identity-resolution","label":"Identity Resolution","docId":"how-it-works/identity-resolution","unlisted":false},{"type":"link","href":"/aegis/docs/how-it-works/integrity-gate","label":"Integrity Gate","docId":"how-it-works/integrity-gate","unlisted":false},{"type":"link","href":"/aegis/docs/how-it-works/scoring","label":"Scoring","docId":"how-it-works/scoring","unlisted":false},{"type":"link","href":"/aegis/docs/how-it-works/feedback-loop","label":"Feedback Loop","docId":"how-it-works/feedback-loop","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"System Architecture","items":[{"type":"link","href":"/aegis/docs/architecture/overview","label":"Phase-by-Phase Overview","docId":"architecture/overview","unlisted":false},{"type":"link","href":"/aegis/docs/architecture/diagrams","label":"Architecture Diagrams","docId":"architecture/diagrams","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"link","href":"/aegis/docs/data-sources","label":"Data Sources","docId":"data-sources","unlisted":false},{"type":"category","label":"API Reference","collapsed":false,"items":[{"type":"link","href":"/aegis/docs/api/","label":"Overview","docId":"api/index","unlisted":false},{"type":"link","href":"/aegis/docs/api/queries","label":"Queries","docId":"api/queries","unlisted":false},{"type":"link","href":"/aegis/docs/api/jobs","label":"Jobs","docId":"api/jobs","unlisted":false},{"type":"link","href":"/aegis/docs/api/candidates","label":"Candidates","docId":"api/candidates","unlisted":false},{"type":"link","href":"/aegis/docs/api/shortlists","label":"Shortlists","docId":"api/shortlists","unlisted":false},{"type":"link","href":"/aegis/docs/api/hitl","label":"HITL","docId":"api/hitl","unlisted":false},{"type":"link","href":"/aegis/docs/api/refit","label":"Refit","docId":"api/refit","unlisted":false},{"type":"link","href":"/aegis/docs/api/system","label":"System","docId":"api/system","unlisted":false}],"collapsible":true},{"type":"link","href":"/aegis/docs/roadmap","label":"Roadmap","docId":"roadmap","unlisted":false}]},"docs":{"api/candidates":{"id":"api/candidates","title":"Candidates","description":"Candidate endpoints expose per-person evidence trails and allow analysts to attach free-text notes to any candidate across queries.","sidebar":"docsSidebar"},"api/hitl":{"id":"api/hitl","title":"HITL Review Queue","description":"When the probabilistic record linker scores a candidate pair between 0.50 and 0.95 confidence (below the auto-link threshold but above the reject threshold), that pair is queued for human review. These endpoints expose the review queue so analysts can confirm, reject, or split ambiguous identity matches.","sidebar":"docsSidebar"},"api/index":{"id":"api/index","title":"API Overview","description":"The Aegis API is a JSON REST API served at:","sidebar":"docsSidebar"},"api/jobs":{"id":"api/jobs","title":"Jobs","description":"When a query is submitted via POST /v1/queries, the pipeline runs as a background async task and a Job record is created immediately. Jobs track status, duration, and candidate count.","sidebar":"docsSidebar"},"api/queries":{"id":"api/queries","title":"Queries","description":"Queries are the core resource. Submitting a query kicks off the full ingestion and ranking pipeline asynchronously and returns a job_id immediately.","sidebar":"docsSidebar"},"api/refit":{"id":"api/refit","title":"Weight Refit","description":"The refit system updates the scoring weight vectors (F1\u2013F7 family weights and \u03b1/\u03b2/\u03b3 exponents) based on accumulated analyst feedback and downstream quality signals. Refits run per specialty and produce a new versioned YAML weight file if the update passes statistical guard checks.","sidebar":"docsSidebar"},"api/shortlists":{"id":"api/shortlists","title":"Shortlists","description":"Shortlists are named collections of candidates curated by an analyst. They are scoped per customer \u2014 each customer sees only their own shortlists.","sidebar":"docsSidebar"},"api/system":{"id":"api/system","title":"System","description":"---","sidebar":"docsSidebar"},"architecture/diagrams":{"id":"architecture/diagrams","title":"Architecture Diagrams","description":"These diagrams reflect the deployed Aegis architecture across all eight phases. Aegis is organized into five layers that data flows through sequentially:","sidebar":"docsSidebar"},"architecture/overview":{"id":"architecture/overview","title":"Phase-by-Phase Overview","description":"Aegis was built incrementally across eight phases, each adding a distinct layer of capability. Later phases depend on earlier ones, and each phase was validated against specific exit criteria before the next one began.","sidebar":"docsSidebar"},"data-sources":{"id":"data-sources","title":"Data Sources","description":"Aegis ingests data from approximately 20 sources across seven categories. Each source feeds into one or more of the three researcher populations (Translational, Drug Discovery, Clinician) and is refreshed on a defined cadence. The tables below list every source, what it provides, how often it is refreshed, and which populations it serves.","sidebar":"docsSidebar"},"how-it-works/data-pipeline":{"id":"how-it-works/data-pipeline","title":"Data Pipeline","description":"Aegis ingests data from approximately 20 sources covering publications, grants, patents, clinical trials, clinician credentials, integrity records, and taxonomy crosswalks. The ingestion layer is the foundation of everything downstream \u2014 scoring, integrity checks, and ranking all depend on having fresh, well-structured data from these sources.","sidebar":"docsSidebar"},"how-it-works/feedback-loop":{"id":"how-it-works/feedback-loop","title":"Feedback Loop","description":"Aegis does not rely on static, hand-tuned scoring weights. Instead, it operates a continuous feedback loop that refines ranking exponents over time based on real-world evidence. The system learns from two sources: expert audit panels and downstream task quality.","sidebar":"docsSidebar"},"how-it-works/identity-resolution":{"id":"how-it-works/identity-resolution","title":"Identity Resolution","description":"A single researcher may appear across dozens of data sources under different name variants, affiliations, and identifiers. \\"J. Smith\\" at Stanford who published in PubMed might be the same person as \\"John A. Smith\\" listed as a PI on an NIH grant and \\"Smith, J.\\" on a patent filing. Without resolving these records into a single unified candidate, scoring would fragment a researcher\'s evidence across multiple incomplete profiles.","sidebar":"docsSidebar"},"how-it-works/integrity-gate":{"id":"how-it-works/integrity-gate","title":"Integrity Gate","description":"Before a candidate receives a ranking score, they pass through the integrity gate. This component determines whether a researcher has disqualifying integrity issues (resulting in exclusion from rankings) or concerning signals (resulting in score reductions). The gate exists to prevent recommending researchers with serious professional or ethical issues, while still being fair to those with minor or contested concerns.","sidebar":"docsSidebar"},"how-it-works/scoring":{"id":"how-it-works/scoring","title":"Scoring","description":"Aegis produces a composite ranking score for each candidate by combining four components: a quality prior, topical fit, recency, and the integrity gate. Each component captures a different dimension of a researcher\'s suitability for a given specialty query.","sidebar":"docsSidebar"},"roadmap":{"id":"roadmap","title":"Roadmap","description":"Phase Status","sidebar":"docsSidebar"},"using-aegis/monitoring-a-job":{"id":"using-aegis/monitoring-a-job","title":"Monitoring a Job","description":"After submitting a query, the pipeline runs in the background. The Jobs pages let you track progress in real time.","sidebar":"docsSidebar"},"using-aegis/reading-results":{"id":"using-aegis/reading-results","title":"Reading Results","description":"The Results page displays ranked candidates with composite scores, evidence trails, and collaboration features.","sidebar":"docsSidebar"},"using-aegis/submitting-a-query":{"id":"using-aegis/submitting-a-query","title":"Submitting a Query","description":"The New Query page is the starting point for expert discovery. Task managers describe the expertise they need in free text, and Aegis handles the rest: MeSH expansion, multi-source fetching, scoring, and ranking.","sidebar":"docsSidebar"},"what-is-aegis":{"id":"what-is-aegis","title":"What is Aegis?","description":"Aegis is an internal researcher-ranking engine built for labeling tasks. Given a specialty query \u2014 say, \\"non-small-cell lung cancer translational research\\" \u2014 Aegis returns a ranked list of the top K candidates, each with a composite score, per-component evidence trail, and integrity flags. The system is designed for internal task managers who need to identify and vet researchers quickly, not as a researcher-facing product.","sidebar":"docsSidebar"}}}}')}}]);